# handling iperf result (statistics & final report)
from ...exceptions import DataTransferVerificationFailure


def get_statistics(direction, iperf_port, client_endpoint, server_endpoint):
    """Return ul and/or dl statistics of iperf"""
    stats = {}
    if (direction == 'ul') or (direction == 'dl'):
        if server_endpoint.iperf_cmd.running():
            pass  # TODO: retrieve interim statistics
        svr_final_result = server_endpoint.iperf_cmd.result()
        client_ip_seen_by_server = server_endpoint.seen_ip_of_other_endpoint(client_endpoint.endpoint_ip)
        stats[direction] = get_server_statistics(svr_final_result,
                                                 iperf_port=iperf_port,
                                                 iperf_client_ip=client_ip_seen_by_server,
                                                 iperf_server_ip=server_endpoint.host_bind_interface_ip)
    else:  # 'simultaneous_ul_dl'
        if server_endpoint.iperf_cmd.running():
            pass  # TODO: retrieve interim statistics
        if client_endpoint.iperf_cmd.running():
            pass  # TODO: retrieve interim statistics
        svr_final_result = server_endpoint.iperf_cmd.result()
        cli_final_result = client_endpoint.iperf_cmd.result()
        ul_client_ip_seen_by_ul_server = server_endpoint.seen_ip_of_other_endpoint(client_endpoint.endpoint_ip)
        stats['ul'] = get_server_statistics(svr_final_result,
                                            iperf_port=iperf_port,
                                            iperf_client_ip=ul_client_ip_seen_by_ul_server,
                                            iperf_server_ip=server_endpoint.host_bind_interface_ip)
        # iperf server running at application-server works as an iperf client
        # connecting to iperf at ue-pc (which opens server port for downlink of --dualmode)
        dl_client_ip_seen_by_dl_server = client_endpoint.seen_ip_of_other_endpoint(server_endpoint.endpoint_ip)
        stats['dl'] = get_server_statistics(cli_final_result,
                                            iperf_port=iperf_port,
                                            iperf_client_ip=dl_client_ip_seen_by_dl_server,
                                            iperf_server_ip=client_endpoint.host_bind_interface_ip)

    return stats


def get_server_statistics(cmd_result, iperf_port, iperf_client_ip, iperf_server_ip):
    """Return server statistics of iperf"""
    # old moler sudo command stores embedded command result under 'cmd_ret' key
    # new version just proxies to embedded command result
    if ('cmd_ret' in cmd_result) and ('CONNECTIONS' in cmd_result['cmd_ret']):
        cmd_result = cmd_result['cmd_ret']

    conn_name_report = _get_server_report_connection_key(cmd_result, iperf_port, iperf_client_ip, iperf_server_ip)
    stats_keys = _get_server_stats_connection_keys(cmd_result, iperf_port, iperf_client_ip, iperf_server_ip)
    if len(stats_keys) > 1:
        # search for multiport summary statistics
        for client_conn, server_conn in stats_keys:
            if client_conn.startswith('multiport'):  # ('multiport@192.168.44.50', '50010@192.168.44.130')
                conn_name_stats = (client_conn, server_conn)
                break
        else:
            client_endpoint_without_port = f"@{iperf_client_ip}"
            server_endpoint = f"{iperf_port}@{iperf_server_ip}"
            key = f"('multiport{client_endpoint_without_port}', '{server_endpoint}')"
            why = "iperf result has following keys only: {}".format(cmd_result['CONNECTIONS'].keys())
            what = "Parallel threads iperf server missing 'multiport' summary statistics"
            msg = f"{what}. Can't find '{key}' key for iperf server statistics - {why}"
            raise DataTransferVerificationFailure(msg)
    else:
        conn_name_stats = stats_keys[0]
    server_report = cmd_result['CONNECTIONS'][conn_name_report]['report']
    server_records = cmd_result['CONNECTIONS'][conn_name_stats]
    return {'report': server_report, 'timeline': server_records}


def _get_server_report_connection_key(cmd_result, iperf_port, iperf_client_ip, iperf_server_ip):
    """Find which key in command result corresponds to server reports"""
    # when running --dualmode we have 2 connections
    # local 10.89.47.150 port 5901 connected with 10.89.47.191 port 39182
    # stats connection name == ('39182@10.89.47.191', '5901@10.89.47.150')
    # report connection name == ('10.89.47.191', '5901@10.89.47.150')
    # local 10.89.47.150 port 34402 connected with 10.89.47.191 port 5901
    # stats connection name == ('34402@10.89.47.150', '5901@10.89.47.191')
    # report connection name == ('10.89.47.150', '5901@10.89.47.191')
    server_results_conn_name = (iperf_client_ip, f"{iperf_port}@{iperf_server_ip}")
    if server_results_conn_name in cmd_result['CONNECTIONS']:
        return server_results_conn_name
    why = "iperf result has following keys only: {}".format(cmd_result['CONNECTIONS'].keys())
    msg = f"Can't find '{server_results_conn_name}' key for iperf server report - {why}"
    raise DataTransferVerificationFailure(msg)


def _get_server_stats_connection_keys(cmd_result, iperf_port, iperf_client_ip, iperf_server_ip):
    """Find which keys in command result correspond to server statistics"""
    # when running --dualmode we have 2 connections
    # local 10.89.47.150 port 5901 connected with 10.89.47.191 port 39182
    # stats connection name == ('39182@10.89.47.191', '5901@10.89.47.150')
    # local 10.89.47.150 port 34402 connected with 10.89.47.191 port 5901
    # stats connection name == ('34402@10.89.47.150', '5901@10.89.47.191')
    srv_stats_keys = []
    server_endpoint = f"{iperf_port}@{iperf_server_ip}"
    client_endpoint_without_port = f"@{iperf_client_ip}"
    for conn_name in cmd_result['CONNECTIONS']:
        if isinstance(conn_name, tuple):
            from_endpoint, to_endpoint = conn_name
            if (to_endpoint == server_endpoint) and (client_endpoint_without_port in from_endpoint):
                srv_stats_keys.append(conn_name)
    if not srv_stats_keys:
        key = f"('xxx{client_endpoint_without_port}', '{server_endpoint}')"
        why = "iperf result has following keys only: {}".format(cmd_result['CONNECTIONS'].keys())
        msg = f"Can't find '{key}' key for iperf server statistics - {why}"
        raise DataTransferVerificationFailure(msg)
    return srv_stats_keys
